refentry.refsect1:
&reftitle.parameters;


  hostname


    The hostname of the SNMP agent (server).
    The hostname may be followed by a port, as in host:port;
    an IPv6 address must be enclosed in square brackets when used with a
    port ([::1]:161). Transport prefixes such as
    udp: or tcp: are not supported.




  security_name

   &snmp.parameter.security-name;



  security_level

   &snmp.parameter.security-level;



  auth_protocol

   &snmp.parameter.auth-protocol;



  auth_passphrase

   &snmp.parameter.auth-passphrase;



  privacy_protocol

   &snmp.parameter.privacy-protocol;



  privacy_passphrase

   &snmp.parameter.privacy-passphrase;



  object_id


    The SNMP object id.




  type

   &snmp.set.type.values;
   &snmp.set.type.values.asn.mapping;
   &snmp.set.type.values.equal.note;
   &snmp.set.type.values.bitset.note;



  value


    The new value




  timeout


    The number of microseconds to wait for a response on each attempt,
    without backoff. A call can therefore last up to
    timeout multiplied by (retries + 1).
    The default, -1, uses the library default of 1 second.




  retries


    The number of times to retry if timeouts occur. The default,
    -1, uses the library default of 5 retries.

&reftitle.returnvalues;

 &return.success;


 If the SNMP host rejects the data type, an E_WARNING message like "Warning: Error in packet. Reason: (badValue) The value given has the wrong type or length." is shown.
 If an unknown or invalid OID is specified the warning probably reads "Could not add variable".

&reftitle.changelog;





    &Version;
    &Description;



   &snmp.changelog.privacy-protocol-aes;


    8.5.0

     Now throws a ValueError when the hostname
     contains null bytes or its length is equal to or greater than 128 bytes,
     when the port is negative or greater than 65535, when the security name is
     empty or contains null bytes, or when the timeout or retries values
     are lower than -1 or too large.


   &snmp.changelog.auth-protocol-sha2;

  &reftitle.examples;

    Using snmp3_set


<?php
  snmp3_set('localhost', 'james', 'authPriv', 'SHA', 'secret007', 'AES', 'secret007', 'IF-MIB::ifAlias.3', 's', "foo");
?>




    Using snmp3_set for setting BITS SNMP object id


<?php
  snmp3_set('localhost', 'james', 'authPriv', 'SHA', 'secret007', 'AES', 'secret007', 'FOO-MIB::bar.42', 'b', '0 1 2 3 4');
// or
  snmp3_set('localhost', 'james', 'authPriv', 'SHA', 'secret007', 'AES', 'secret007', 'FOO-MIB::bar.42', 'x', 'F0');
?>
